import java.util.*;

public class Test {
    private static int countInsideWords(String s) {
        StringTokenizer st = new StringTokenizer(s, "_");
        int total = 0;
        while (st.hasMoreTokens()) {
            String token = st.nextToken();
            boolean hasLetter = false;
            for (int i = 0; i < token.length(); i++) {
                if (Character.isLetter(token.charAt(i))) {
                    hasLetter = true;
                    break;
                }
            }
            if (hasLetter) total++;
        }
        return total;
    }

    private static int countLetters(String s) {
        int letters = 0;
        for (int i = 0; i < s.length(); i++) {
            if (Character.isLetter(s.charAt(i))) letters++;
        }
        return letters;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        str += "^";
        n++;
        char[] input = new char[256];
        for (int i = 0; i < n; i++) input[i] = str.charAt(i);

        ArrayList<String> inside = new ArrayList<>();
        int flag = 0;
        StringBuilder cur = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = input[i];
            if (c == '(') {
                flag = 1;
                input[i] = '^';
                continue;
            } else if (c == ')') {
                flag = 0;
                inside.add(cur.toString());
                input[i] = '^';
                cur.setLength(0);
            }
            if (flag == 1) {
                cur.append(input[i]);
                input[i] = '^';
            }
        }

        String cleaned = n > 0 ? new String(input, 0, n) : "";
        int lastCaret = cleaned.lastIndexOf('^');
        int max = 0;
        if (lastCaret >= 0) {
            StringTokenizer st = new StringTokenizer(cleaned.substring(0, lastCaret + 1), "^_");
            while (st.hasMoreTokens()) {
                int letters = countLetters(st.nextToken());
                if (letters > max) max = letters;
            }
        }

        int count = 0;
        for (String segment : inside) {
            count += countInsideWords(segment);
        }

        System.out.println(max + " " + count);
    }
}
